def test_light_mode_order_is_frozen():
    """Enum values are stored by their position in the list in older blenders, so new modes may only be appended.

    Moving "Current scene lighting" anywhere but the end would silently change the light mode of every saved file.
    """
    assert [item[0] for item in cg.LIGHT_MODE_ITEMS] == [
        cg.LIGHT_MODE_FIXED, cg.LIGHT_MODE_BBOX, cg.LIGHT_MODE_NO_SHADOW, cg.LIGHT_MODE_ACROSS_STRANDS,
        cg.LIGHT_MODE_SCENE]


def test_every_light_mode_has_its_own_base_energy():
    for key, _label, _description in cg.LIGHT_MODE_ITEMS:
        assert key in cg.LIGHT_MODE_BASE_ENERGY, f"{key} would fall back to the generic wattage"


def test_scene_lighting_adds_no_energy():
    assert cg.light_base_energy(cg.LIGHT_MODE_SCENE) == 0.0


def test_unknown_light_mode_gets_the_generic_energy():
    assert cg.light_base_energy("NOT_A_MODE") == 200.0


@pytest.mark.parametrize("items", [cg.CARDS_MODE_ITEMS, cg.BAKE_TARGET_ITEMS, cg.LIGHT_MODE_ITEMS,
                                   cg.SELECTION_METHOD_ITEMS])
def test_option_lists_have_unique_keys_and_texts(items):
    keys = [item[0] for item in items]
    assert len(keys) == len(set(keys))
    for key, label, description in items:
        assert label and description, f"{key} needs a label and a tooltip"


def test_mode_groups_only_name_existing_modes():
    modes = {item[0] for item in cg.CARDS_MODE_ITEMS}
    targets = {item[0] for item in cg.BAKE_TARGET_ITEMS}
    assert set(cg.STRAND_BASED_MODES) <= modes
    assert set(cg.CLUSTER_MODES) <= modes
    assert set(cg.BODY_BAKE_TARGETS) <= targets


