# ---------------------------------------------------------------------------
# Node groups: the sockets each mode offers
# ---------------------------------------------------------------------------

_SELECTION_SOCKETS = {"Density", "Seed", "Weight vertex group"}
_TILES_SOCKETS = _SELECTION_SOCKETS | {"Cluster strength", "Segments", "Offset", "Scale", "Card width",
                                       "Card length", "Width random", "Length random", "Tilt random"}
_RIBBON_SOCKETS = _SELECTION_SOCKETS | {"Cluster strength", "Offset", "Profile steps", "Card width", "Taper",
                                        "Twist", "Extend tip"}
_SHELL_SOCKETS = {"Volume density", "Seed", "Weight vertex group", "Strand samples", "Voxel size",
                  "Strand radius", "Adaptivity", "Hug strands", "Smooth iterations"}


def _build(mode, selection_method, basemesh, name):
    if mode == cg.CARDS_MODE_TILES:
        return cg.build_tiles_node_group(name, selection_method, basemesh)
    if mode == cg.CARDS_MODE_RIBBON:
        return cg.build_ribbon_node_group(name, selection_method, basemesh)
    if mode == cg.CARDS_MODE_SHELL:
        return cg.build_shell_node_group(name, basemesh)
    if mode == cg.CARDS_MODE_CLUSTER_RIBBON:
        return cg.build_cluster_ribbon_node_group(name, basemesh)
    raise ValueError(mode)


@pytest.mark.parametrize("selection_method, extra", [(cg.SELECTION_METHOD_RANDOM, set()),
                                                     (cg.SELECTION_METHOD_EVERY_NTH, {"Jitter"}),
                                                     (cg.SELECTION_METHOD_POISSON, {"Poisson radius"})])
@pytest.mark.parametrize("mode, expected", [(cg.CARDS_MODE_TILES, _TILES_SOCKETS),
                                            (cg.CARDS_MODE_RIBBON, _RIBBON_SOCKETS)])
def test_strand_based_modes_offer_their_sockets(scratch, mode, expected, selection_method, extra):
    scalp = make_grid("cardgen_scalp")
    node_group = _build(mode, selection_method, scalp, f"cardgen_{mode}_{selection_method}")
    assert set(_input_sockets(node_group)) - {"Geometry"} == expected | extra


