@pytest.mark.parametrize("mode", [cg.CARDS_MODE_TILES, cg.CARDS_MODE_RIBBON, cg.CARDS_MODE_SHELL,
                                  cg.CARDS_MODE_CLUSTER_RIBBON, "BODY_SHELL"])
def test_socket_defaults_match_the_property_definitions(scratch, mode):
    """The panel properties and the sockets they drive are defined in two places, which have to agree.

    A property whose default differs from its socket shows one value in the panel while the cards are built
    with another, until the user touches the slider.
    """
    if mode == "BODY_SHELL":
        node_group = cg.build_body_shell_node_group("cardgen_defaults_body_shell")
    else:
        node_group = _build(mode, cg.SELECTION_METHOD_RANDOM, make_grid("cardgen_defaults_scalp"),
                            f"cardgen_defaults_{mode}")
    sockets = _input_sockets(node_group)
    overrides = hairproperties.CARDS_MODE_DEFAULT_OVERRIDES.get(mode, {})

    checked = 0
    for name, (socket_name, value_range, default) in hairproperties.DYNAMIC_CARDS_PROPS_DEFINITIONS.items():
        socket = sockets.get(socket_name)
        if socket is None:
            continue
        default = overrides.get(name, default)
        assert socket.default_value == pytest.approx(default), f"{name} defaults differ in mode {mode}"
        if value_range is not None and hasattr(socket, "min_value"):
            assert (socket.min_value, socket.max_value) == pytest.approx(value_range), f"{name} ranges differ in {mode}"
        checked += 1
    assert checked >= 2, f"no properties matched any socket of mode {mode}"


def test_every_socket_has_a_property(scratch):
    """A socket without a property is a setting the user can never reach from the panel."""
    socket_names = {definition[0] for definition in hairproperties.DYNAMIC_CARDS_PROPS_DEFINITIONS.values()}
    scalp = make_grid("cardgen_unreachable_scalp")
    groups = [_build(mode, method, scalp, f"cardgen_unreachable_{mode}_{method}")
              for mode in (cg.CARDS_MODE_TILES, cg.CARDS_MODE_RIBBON)
              for method in (cg.SELECTION_METHOD_RANDOM, cg.SELECTION_METHOD_EVERY_NTH, cg.SELECTION_METHOD_POISSON)]
    groups += [cg.build_shell_node_group("cardgen_unreachable_shell", scalp),
               cg.build_cluster_ribbon_node_group("cardgen_unreachable_cluster", scalp),
               cg.build_body_shell_node_group("cardgen_unreachable_body")]
    for node_group in groups:
        missing = set(_input_sockets(node_group)) - socket_names - {"Geometry"}
        assert not missing, f"{node_group.name} has sockets no property drives: {missing}"


@pytest.mark.parametrize("mode", [cg.CARDS_MODE_TILES, cg.CARDS_MODE_RIBBON, cg.CARDS_MODE_SHELL,
                                  cg.CARDS_MODE_CLUSTER_RIBBON])
def test_socket_names_are_unique(scratch, mode):
    """The properties find their socket by name, so a second socket of the same name can never be reached."""
    node_group = _build(mode, cg.SELECTION_METHOD_RANDOM, make_grid("cardgen_unique_scalp"), f"cardgen_unique_{mode}")
    names = [item.name for item in node_group.interface.items_tree
             if getattr(item, "item_type", None) == "SOCKET" and item.in_out == "INPUT"]
    duplicates = sorted({name for name in names if names.count(name) > 1})
    assert not duplicates, f"{mode} has duplicate inputs {duplicates}"


