def _hair_for_cards(name="cardgen_hair"):
    """Twenty strands spread over a 0.4 x 0.4 patch, 0.2 long, growing up from the XY plane."""
    roots = [(-0.15 + 0.1 * column, -0.15 + 0.1 * row, 0.0) for row in range(4) for column in range(4)]
    roots += [(-0.05, 0.0, 0.0), (0.05, 0.0, 0.0), (0.0, -0.05, 0.0), (0.0, 0.05, 0.0)]
    strands = [[(root[0], root[1], 0.2 * step / 7.0) for step in range(8)] for root in roots]
    return make_hair_curves(name, strands)


def _evaluate_cards(hair_obj, node_group, inputs):
    """Put the group on a copy of the hair and convert it to a mesh, which is what the bake does."""
    probe = hair_obj.copy()
    probe.data = hair_obj.data.copy()
    link(probe)
    modifier = probe.modifiers.new(name=hairproperties.CARDS_MODIFIER_NAME, type='NODES')
    modifier.node_group = node_group
    for socket_name, value in inputs.items():
        identifier = find_socket(node_group, socket_name)
        assert identifier is not None, f"{socket_name} is not an input of {node_group.name}"
        ModifierService.set_node_group_input(modifier, identifier, value)
    select(probe)
    bpy.ops.object.convert(target='MESH')
    return probe


def _faces(obj):
    """Faces of a converted probe. Nothing to convert leaves the object as curves, which means no cards at all."""
    return len(obj.data.polygons) if obj.type == 'MESH' else 0


@pytest.mark.parametrize("mode", [cg.CARDS_MODE_TILES, cg.CARDS_MODE_RIBBON])
def test_strand_modes_produce_cards_with_uvs(scratch, mode):
    hair_obj = _hair_for_cards()
    node_group = _build(mode, cg.SELECTION_METHOD_RANDOM, None, f"cardgen_eval_{mode}")
    cards = _evaluate_cards(hair_obj, node_group, {"Density": 1.0})
    assert len(cards.data.polygons) > 0
    assert cg.CARDS_UV_MAP in cards.data.uv_layers, "the bake relies on the generator's own UV map"
    for uv in cards.data.uv_layers[cg.CARDS_UV_MAP].data:
        assert -0.001 <= uv.uv[0] <= 1.001 and -0.001 <= uv.uv[1] <= 1.001


@pytest.mark.parametrize("mode", [cg.CARDS_MODE_TILES, cg.CARDS_MODE_RIBBON])
def test_zero_density_produces_nothing(scratch, mode):
    hair_obj = _hair_for_cards()
    node_group = _build(mode, cg.SELECTION_METHOD_RANDOM, None, f"cardgen_eval_empty_{mode}")
    cards = _evaluate_cards(hair_obj, node_group, {"Density": 0.0})
    assert _faces(cards) == 0


def test_more_density_keeps_more_strands(scratch):
    hair_obj = _hair_for_cards()
    node_group = cg.build_ribbon_node_group("cardgen_eval_density", cg.SELECTION_METHOD_RANDOM, None)
    few = _faces(_evaluate_cards(hair_obj, node_group, {"Density": 0.3, "Seed": 3}))
    all_of_them = _faces(_evaluate_cards(hair_obj, node_group, {"Density": 1.0, "Seed": 3}))
    assert few < all_of_them


def test_every_nth_keeps_about_the_right_share(scratch):
    """Density 0.5 with no jitter keeps every second strand: half of the twenty."""
    hair_obj = _hair_for_cards()
    node_group = cg.build_ribbon_node_group("cardgen_eval_nth", cg.SELECTION_METHOD_EVERY_NTH, None)
    everything = len(_evaluate_cards(hair_obj, node_group, {"Density": 1.0, "Jitter": 0.0}).data.polygons)
    half = len(_evaluate_cards(hair_obj, node_group, {"Density": 0.5, "Jitter": 0.0}).data.polygons)
    assert half == pytest.approx(everything / 2, abs=everything / 20)


def test_weight_vertex_group_masks_the_strands(scratch):
    """Strands over a part of the scalp painted with weight 0 never become cards."""
    hair_obj = _hair_for_cards()
    scalp = make_grid("cardgen_weight_scalp", faces_per_side=8)
    group = scalp.vertex_groups.new(name="keep_left")
    group.add([vertex.index for vertex in scalp.data.vertices if vertex.co.x < -0.01], 1.0, 'REPLACE')
    group.add([vertex.index for vertex in scalp.data.vertices if vertex.co.x >= -0.01], 0.0, 'REPLACE')

    node_group = cg.build_ribbon_node_group("cardgen_eval_weight", cg.SELECTION_METHOD_RANDOM, scalp)
    cards = _evaluate_cards(hair_obj, node_group, {"Density": 1.0, "Weight vertex group": "keep_left"})
    assert len(cards.data.polygons) > 0
    assert max(vertex.co.x for vertex in cards.data.vertices) < 0.0

    unmasked = _evaluate_cards(hair_obj, node_group, {"Density": 1.0, "Weight vertex group": "no such group"})
    assert max(vertex.co.x for vertex in unmasked.data.vertices) > 0.0, \
        "a misspelled vertex group must mean weight 1, not an empty asset"


def test_offset_pushes_cards_off_the_scalp(scratch):
    hair_obj = _hair_for_cards()
    scalp = make_grid("cardgen_offset_scalp")
    node_group = cg.build_ribbon_node_group("cardgen_eval_offset", cg.SELECTION_METHOD_RANDOM, scalp)
    flat = _evaluate_cards(hair_obj, node_group, {"Density": 1.0, "Offset": 0.0})
    lifted = _evaluate_cards(hair_obj, node_group, {"Density": 1.0, "Offset": 0.05})
    lowest = lambda obj: min(vertex.co.z for vertex in obj.data.vertices)
    assert lowest(lifted) == pytest.approx(lowest(flat) + 0.05, abs=0.01)


def test_shell_wraps_the_strands_in_a_closed_mesh(scratch):
    hair_obj = _hair_for_cards()
    node_group = cg.build_shell_node_group("cardgen_eval_shell", None)
    shell = _evaluate_cards(hair_obj, node_group, {"Volume density": 1.0})
    assert len(shell.data.polygons) > 0
    zs = [vertex.co.z for vertex in shell.data.vertices]
    assert min(zs) < 0.05 and max(zs) > 0.15, "the shell should span the whole length of the strands"


